1	/**
2	 * target-state.ts — read whether an issue or pull request is open, closed, or merged.
3	 *
4	 * The one lookup behind every guard in `domain/work/closed-target.ts`, which decides what to
5	 * do with the answer. Three callers need it — the slash-command guard, the stop-on-close
6	 * job, and `dispatchRunner` — and a fourth will be added by whoever adds the next way
7	 * to start an agent, so it is a function rather than three spellings of one `gh` call.
8	 *
9	 * ## Why the issues endpoint, and not `gh pr view` / `gh issue view`
10	 *
11	 * `GET /repos/{owner}/{repo}/issues/{n}` answers for both. `gh issue view` on a pull
12	 * request number refuses, and picking the right one first would mean already knowing
13	 * which kind of thing the number names — which is the trap #811 is about, one layer
14	 * down: `repository.issue(number:)` does not resolve a pull request either, and every
15	 * caller that passed one got an empty answer rather than an error.
16	 *
17	 * The same response carries `pull_request.merged_at`, which is the only way to tell a
18	 * merged pull request from a closed one. That distinction is not cosmetic: GitHub
19	 * cannot reopen a merged pull request, so a notice telling somebody to reopen one is
20	 * advice that cannot be taken.
21	 *
22	 * ## Why `ghRead`
23	 *
24	 * A failure here refuses to start work. That is the right answer for "this target is
25	 * closed" and the wrong one for "GitHub returned 504", and the two are indistinguishable
26	 * at this level — so the retry happens below, and only a failure that outlasts it
27	 * becomes `unknown`. Without that, a blip would stall a chain that had nothing wrong
28	 * with it.
29	 */
30	import { ghRead } from "./gh.ts";
31	import { issueOutcome, pullRequestOutcome } from "./outcome.ts";
32	import type { TargetState } from "../../domain/work/closed-target.ts";
33	import type { NodeKind } from "../../domain/work/work-tree.ts";
34	
35	interface IssueOrPr {
36	  state?: string;
37	  /** Why a closed ISSUE is closed. Absent on a pull request, which says `merged_at` instead. */
38	  state_reason?: string | null;
39	  pull_request?: { merged_at?: string | null };
40	  labels?: { name?: string }[];
41	}
42	
43	/**
44	 * The state of `number` in `repo`, or `unknown` with the reason.
45	 *
46	 * `repo` may be empty when the caller runs inside a checkout of the repository it
47	 * means; `gh` fills the placeholders in from the remote. Never throws — the callers
48	 * all have something to say about not knowing, and none of them have anything to do
49	 * with an exception.
50	 */
51	export function readTargetState(number: number | string, repo?: string): TargetState {
52	  const path = repo ? `repos/${repo}/issues/${number}` : `repos/{owner}/{repo}/issues/${number}`;
53	  const { code, stdout, stderr } = ghRead("api", path);
54	  if (code !== 0) {
55	    return { known: false, why: (stderr || stdout || `gh exited ${code}`).trim().split("\n")[0] ?? "" };
56	  }
57	
58	  let parsed: IssueOrPr;
59	  try {
60	    parsed = JSON.parse(stdout) as IssueOrPr;
61	  } catch {
62	    return { known: false, why: "the response was not JSON" };
63	  }
64	
65	  // An unrecognised state is not "open". GitHub answers `open` or `closed` here, so a
66	  // third value means this is reading something it does not understand, and the
67	  // permissive reading is the one that lets work through.
68	  const isPr = parsed.pull_request !== undefined;
69	  const kind: NodeKind = isPr ? "pull-request" : "issue";
70	  // The names the node is wearing, read off the same response. A label without a
71	  // name is not a label anybody asked for; dropping it costs the caller one removal
72	  // it would have made anyway.
73	  const labels = (parsed.labels ?? [])
74	    .map((label) => label.name ?? "")
75	    .filter((name) => name !== "");
76	  if (parsed.state === "open") return { known: true, kind, state: "open", labels };
77	  if (parsed.state === "closed") {
78	    return {
79	      known: true,
80	      kind,
81	      state: isPr
82	        ? pullRequestOutcome(Boolean(parsed.pull_request?.merged_at))
83	        : issueOutcome(parsed.state_reason),
84	      labels,
85	    };
86	  }
87	  return { known: false, why: `unrecognised state ${JSON.stringify(parsed.state ?? null)}` };
88	}

